module beautiful_number(\n    input clk,\n    input rst_n,\n    input start,\n    input [3:0] n,\n    input [3:0] k,\n    input [3:0] digits [0:15],\n    output reg [3:0] m,\n    output reg [3:0] y_digits [0:15],\n    output reg done\n);\n\n    localparam [2:0] IDLE = 3'd0;\n    localparam [2:0] INIT = 3'd1;\n    localparam [2:0] COMPARE = 3'd2;\n    localparam [2:0] INCREMENT = 3'd3;\n    localparam [2:0] OUTPUT = 3'd4;\n    localparam [2:0] DONE = 3'd5;\n\n    reg [2:0] state;\n    reg [3:0] pattern [0:7];\n    reg [3:0] i;\n    reg [3:0] j;\n    reg [3:0] carry;\n    reg [1:0] cmp_flag;\n    reg [3:0] pattern_digit;\n    reg [3:0] input_digit;\n\n    integer idx;\n\n    always @(posedge clk or negedge rst_n) begin\n        if (!rst_n) begin\n            state <= IDLE;\n            done <= 1'b0;\n            m <= 4'd0;\n            for (idx = 0; idx < 16; idx = idx + 1) begin\n                y_digits[idx] <= 4'd0;\n            end\n            for (idx = 0; idx < 8; idx = idx + 1) begin\n                pattern[idx] <= 4'd0;\n            end\n            i <= 4'd0;\n            j <= 4'd0;\n            carry <= 4'd0;\n            cmp_flag <= 2'd0;\n        end else begin\n            case (state)\n                IDLE: begin\n                    done <= 1'b0;\n                    if (start) begin\n                        for (i = 0; i < 8; i = i + 1) begin\n                            if (i < k) begin\n                                pattern[i] <= digits[i];\n                            end else begin\n                                pattern[i] <= 4'd0;\n                            end\n                        end\n                        i <= 4'd0;\n                        cmp_flag <= 2'd0;\n                        state <= INIT;\n                    end\n                end\n                \n                INIT: begin\n                    i <= 4'd0;\n                    state <= COMPARE;\n                end\n                \n                COMPARE: begin\n                    if (i < n) begin\n                        if (i < k) begin\n                            pattern_digit <= pattern[i];\n                        end else begin\n                            pattern_digit <= pattern[i - k];\n                        end\n                        input_digit <= digits[i];\n                        \n                        if (cmp_flag == 2'd0) begin\n                            if (input_digit > pattern_digit) begin\n                                cmp_flag <= 2'd1;\n                            end else if (input_digit < pattern_digit) begin\n                                cmp_flag <= 2'd2;\n                            end\n                        end\n                        i <= i + 1;\n                    end else begin\n                        if (cmp_flag == 2'd1) begin\n                            i <= k - 1;\n                            carry <= 4'd1;\n                            state <= INCREMENT;\n                        end else begin\n                            state <= OUTPUT;\n                        end\n                    end\n                end\n                \n                INCREMENT: begin\n                    if (carry > 0 && i >= 0 && i < 8) begin\n                        if (pattern[i] + carry >= 4'd10) begin\n                            pattern[i] <= pattern[i] + carry - 4'd10;\n                            carry <= 4'd1;\n                        end else begin\n                            pattern[i] <= pattern[i] + carry;\n                            carry <= 4'd0;\n                        end\n                        \n                        if (i == 0 && carry > 0) begin\n                            pattern[0] <= 4'd1;\n                            for (j = 1; j < k; j = j + 1) begin\n                                pattern[j] <= 4'd0;\n                            end\n                            state <= OUTPUT;\n                        end else if (carry > 0) begin\n                            i <= i - 1;\n                        end else begin\n                            state <= OUTPUT;\n                        end\n                    end else begin\n                        state <= OUTPUT;\n                    end\n                end\n                \n                OUTPUT: begin\n                    m <= n;\n                    for (i = 0; i < 16; i = i + 1) begin\n                        if (i < n) begin\n                            if (i < k) begin\n                                y_digits[i] <= pattern[i];\n                            end else begin\n                                y_digits[i] <= pattern[i - k];\n                            end\n                        end else begin\n                            y_digits[i] <= 4'd0;\n                        end\n                    end\n                    state <= DONE;\n                end\n                \n                DONE: begin\n                    done <= 1'b1;\n                    state <= IDLE;\n                end\n                \n                default: state <= IDLE;\n            endcase\n        end\n    end\nendmodule